PAGE = dict(
    slug='y_label',
    title='Pane::y_label',
    signature='Pane& Pane::y_label(std::string label)',
    intro="Sets the label of the y axis: the text drawn beside the axis that says what it measures. It is separate from the pane's own title ([`Pane::title`](title.md), drawn above the whole plot) and from the shared caption of an alignment group ([`Studio::y_caption`](../studio/y_caption.md), drawn once for several panes); the three can be used together. The text is stored in `y_axis().label`, where it can be read back; there is no separate getter.\n\nThe setter takes any text. An empty string clears the label and gives exactly the figure that never had one, a second call replaces the first, and text between dollar signs is typeset as math. The label is read when the figure is rendered, so it can be set before or after the traces. Its distance from the axis is [`y_label_gap`](y_label_gap.md) and its angle is [`y_label_rotation`](y_label_rotation.md); the axis tick labels are separate ([`y_tick_labels`](y_tick_labels.md)).\n\nThe placement of the y label is automatic. While the label is short it stands upright at the top of the axis; once its upright width passes `y_label_upright_max_width_share` of the pane (0.15 by default; see [Style options](../types/StyleOptions.md)) it is turned to run vertically and centred along the axis, outside the tick labels, the way `y_label_centered()` places it. [`y_label_rotation`](y_label_rotation.md) and [`y_label_centered`](y_label_centered.md) are choices of yours that the automatic placement never overrides; [`y_label_full`](y_label_full.md) keeps a long turned label whole.",
    parameters='**label** (`std::string`)\n    The label text. Empty clears the label.',
    returns='`Pane&`\n    The same pane, for chaining.',
    examples=[
        dict(id='basic', text='Setting the y label. The label is stored in `y_axis().label` and drawn beside the y axis.',
             code='auto fig = studio("y_label_basic");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\nstd::cout << "before: \'" << pane.y_axis().label << "\'\\n";\npane.y_label("Elapsed time (s)");\nstd::cout << "after: \'" << pane.y_axis().label << "\'\\n";\nstd::cout << "drawn: " << (fig.to_svg().find(">Elapsed time (s)<") != std::string::npos) << "\\n";\nfig.show();'),
        dict(id='replace_clear', text='Replacing and clearing. A second call replaces the text, and an empty string clears it: the figure is then exactly the figure that never had a label.',
             code='auto build = [&](const char* first, const char* second) {\n  auto fig = studio("y_label_clear");\n  auto& pane = fig.pane2("p");\n  pane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\n  if (first) pane.y_label(first);\n  if (second) pane.y_label(second);\n  return fig.to_svg();\n};\nstd::cout << "replaced: " << (build("old", "new").find(">new<") != std::string::npos) << ", old still drawn: " << (build("old", "new").find(">old<") != std::string::npos) << "\\n";\nstd::cout << "cleared == never set: " << (build("temporary", "") == build(nullptr, nullptr)) << "\\n";\nauto fig = studio("y_label_clear_out");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\npane.y_label("Final label");\nfig.show();'),
        dict(id='distinct', text="Not the title and not a shared caption. The pane's title, its y label and a figure-level caption are three separate texts; each is set by its own call and each is drawn in its own place.",
             code='auto fig = studio("y_label_distinct");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\npane.title("Pane title");\npane.y_label("Axis label");\npane.align_y("group");\nfig.y_caption("group", "Shared caption");\nconst std::string svg = fig.to_svg();\nstd::cout << "title: " << (svg.find(">Pane title<") != std::string::npos) << ", label: " << (svg.find(">Axis label<") != std::string::npos) << ", caption: " << (svg.find(">Shared caption<") != std::string::npos) << "\\n";\nfig.show();'),
        dict(id='independent', text='Per axis. Setting the y label leaves the labels of the other axes empty, and each axis keeps its own text.',
             code='auto fig = studio("y_label_independent");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\npane.y_label("this axis only");\nstd::cout << "x: \'" << pane.x_axis().label << "\', y: \'" << pane.y_axis().label << "\', z: \'" << pane.z_axis().label << "\'\\n";\npane.x_label("x text").y_label("y text").z_label("z text");\nstd::cout << "all set: \'" << pane.x_axis().label << "\', \'" << pane.y_axis().label << "\', \'" << pane.z_axis().label << "\'\\n";\nfig.show();'),
        dict(id='math', text='Math text. A label with `$...$` is typeset, so Greek letters and subscripts appear as symbols instead of the raw markup.',
             code='auto fig = studio("y_label_math");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\npane.y_label("$\\\\sigma_t$ (volatility)");\nconst std::string svg = fig.to_svg();\nstd::cout << "raw markup drawn: " << (svg.find("$\\\\sigma_t$") != std::string::npos) << "\\n";\nfig.show();'),
        dict(id='long_default', text="A long y label turns itself. Left alone, a short label is written upright at the top of the axis; a label whose upright width would pass 15 per cent of the pane is turned to run vertically and is centred beside the axis, so it is not cut by the figure's edge. A rotation set by hand is never overridden: with `y_label_rotation(0.0)` the long label stays upright.",
             code='auto fig = studio("y_label_long_default");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{3, 5, 4, 6});\nauto look = [](const std::string& svg, const std::string& text) {\n  const auto hit = svg.find(">" + text + "<");\n  if (hit == std::string::npos) return std::string("absent");\n  const auto open = svg.rfind("<text", hit);\n  const std::string tag = svg.substr(open, hit - open);\n  const auto anchor = tag.find("text-anchor=\\"");\n  std::string out = "anchor " + tag.substr(anchor + 13, tag.find(\'"\', anchor + 13) - anchor - 13);\n  const auto rot = tag.find("rotate(");\n  out += rot == std::string::npos ? ", upright" : ", rotated " + tag.substr(rot + 7, tag.find(\' \', rot) - rot - 7);\n  return out;\n};\nconst std::string longer = "Average household income per adult in the region (USD per year)";\npane.y_label("Income (USD)");\nstd::cout << "short label:        " << look(fig.to_svg(), "Income (USD)") << "\\n";\npane.y_label(longer);\nstd::cout << "long label:         " << look(fig.to_svg(), longer) << "\\n";\npane.y_label_rotation(0.0);\nstd::cout << "long, rotation set: " << look(fig.to_svg(), longer) << "\\n";\npane.clear_y_label_rotation();\nfig.show();'),
    ],
    notes='- Not `noexcept`: it moves the text into the pane.\n- The label of an axis does not change the axis range or its ticks.',
    see=['[`Pane::y_label_gap`](y_label_gap.md), [`y_label_rotation`](y_label_rotation.md): where and at what angle it is drawn.', '[`Studio::y_caption`](../studio/y_caption.md): one caption shared by aligned panes.', '[`Pane::title`](title.md): the title of the pane.', '[`Pane::y_label_centered`](y_label_centered.md), [`y_label_full`](y_label_full.md): where a long label stands and whether it is kept whole.', '[`Pane::x_label`](x_label.md): the same setting for the x axis.', '[`Pane::z_label`](z_label.md): the same setting for the z axis.'],
)
